from dataclasses import replace
from unittest.mock import patch
from bloomerp.communication.builtins.voip.registry import VOIP_PROVIDER_REGISTRY

# Generated by manage.py generate_test_cases.
from bloomerp.models.communication.voip.voip_connection import VoIPConnection
from bloomerp.tests.views.communication.voip.provider_fixtures import (
    AlternateProviderFixtures,
)
from django.core import signing
from django.http import HttpResponse
from twilio.base.exceptions import TwilioRestException
from bloomerp.tests.base import (
    BloomerpDetailViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestCreateVoIpnumberView(AlternateProviderFixtures, BloomerpDetailViewTestCase):
    """Tests class `CreateVoIPNumberView` from `bloomerp/views/communication/create_voip_number.py`."""

    view_name = "create_voip_number"
    model = VoIPConnection

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Describe the observable request contracts for this endpoint."""
        # Add only the route scenarios this callable needs.
        return [
            RequestScenario(
                name="Provider without provisioning schemas rejects number creation",
                user=self.normal_user,
                prepare=[
                    self.prepare_alternate_provider,
                    self.grant_connection_access,
                    self.prepare_no_provisioning,
                ],
                expected=ExpectedResult(status_code=404),
            ),
            RequestScenario(
                name="Alternate provider owns search and purchase controls",
                user=self.normal_user,
                prepare=[self.prepare_alternate_provider, self.grant_connection_access],
                query_params={"territory": "North"},
                expected=ExpectedResult(
                    response_validators=[self.verify_alternate_search]
                ),
            ),
            RequestScenario(
                name="Alternate provider provisions typed options",
                method="POST",
                user=self.normal_user,
                prepare=[
                    self.prepare_alternate_provider,
                    self.grant_connection_access,
                    self.prepare_alternate_purchase,
                ],
                expected=ExpectedResult(
                    status_code=302,
                    response_validators=[self.verify_alternate_purchase],
                ),
            ),
            RequestScenario(
                name="Alternate provider rejects invalid plan before carrier purchase",
                method="POST",
                user=self.normal_user,
                prepare=[
                    self.prepare_alternate_provider,
                    self.grant_connection_access,
                    self.prepare_invalid_plan,
                ],
                expected=ExpectedResult(response_validators=[self.verify_no_purchase]),
            ),
            RequestScenario(
                name="Provider-owned transport errors are sanitized",
                user=self.normal_user,
                prepare=[
                    self.prepare_alternate_provider,
                    self.grant_connection_access,
                    self.prepare_search_failure,
                ],
                query_params={"territory": "North"},
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("Number search failed"),
                        self.does_not_contain_text("private-provider-error"),
                    ]
                ),
            ),
            RequestScenario(
                name="Search with object change permission",
                user=self.normal_user,
                prepare=[self.prepare_account, self.grant_connection_access],
                query_params={"country": "BE", "kind": "mobile"},
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("+32470000008"),
                        self.no_secrets,
                    ]
                ),
            ),
            RequestScenario(
                name="HTMX search returns selectable offers in the detail fragment",
                user=self.normal_user,
                prepare=[self.prepare_account, self.grant_connection_access],
                query_params={"country": "BE", "kind": "mobile"},
                headers={"HX-Request": "true", "HX-Target": "detail-view-content"},
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("+32470000008"),
                        self.contains_text('hx-target="#detail-view-content"'),
                        self.contains_text('name="selection"'),
                        self.does_not_contain_text('<html'),
                        self.no_secrets,
                    ]
                ),
            ),
            RequestScenario(
                name="Owner without change grant cannot search",
                user=self.normal_user,
                prepare=self.prepare_owner_without_permission,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Provision selected number",
                method="POST",
                user=self.normal_user,
                prepare=[
                    self.prepare_account,
                    self.grant_connection_access,
                    self.prepare_purchase,
                ],
                expected=ExpectedResult(
                    status_code=302, response_validators=[self.verify_purchase]
                ),
            ),
            RequestScenario(
                name="Reject tampered selection",
                method="POST",
                user=self.normal_user,
                prepare=[
                    self.prepare_account,
                    self.grant_connection_access,
                    self.prepare_tampered,
                ],
                expected=ExpectedResult(response_validators=[self.verify_no_purchase]),
            ),
            RequestScenario(
                name="Provisioning rejection exposes only the safe provider error code",
                method="POST",
                user=self.normal_user,
                prepare=[
                    self.prepare_account,
                    self.grant_connection_access,
                    self.prepare_purchase,
                    self.prepare_provisioning_failure,
                ],
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("Provider error code: 21422."),
                        self.does_not_contain_text("private-provider-error"),
                        self.does_not_contain_text("private-request-uri"),
                        self.no_secrets,
                    ]
                ),
            ),
            RequestScenario(
                name="Charges require explicit confirmation",
                method="POST",
                user=self.normal_user,
                prepare=[
                    self.prepare_account,
                    self.grant_connection_access,
                    self.prepare_unconfirmed,
                ],
                expected=ExpectedResult(response_validators=[self.verify_no_purchase]),
            ),
        ]

    def prepare_purchase(self, scenario: RequestScenario) -> None:
        """Sign an offer scoped to the acting user and selected connection."""
        scenario.data = {
            "selection": signing.dumps(
                {
                    "connection": str(self.connection.pk),
                    "user": str(self.normal_user.pk),
                    "number": "+32470000008",
                },
                salt="voip-number-offer",
            ),
            "name": "Reception",
            "confirm": "on",
        }

    def prepare_provisioning_failure(self, scenario: RequestScenario) -> None:
        """Reject a carrier purchase with a code and private transport details."""
        self.adapter.provision_number.side_effect = TwilioRestException(
            status=400,
            uri="private-request-uri",
            msg="private-provider-error",
            code=21422,
        )

    def prepare_tampered(self, scenario: RequestScenario) -> None:
        """Alter the signed offer without changing its valid form fields."""
        self.prepare_purchase(scenario)
        scenario.data["selection"] += "tampered"

    def prepare_unconfirmed(self, scenario: RequestScenario) -> None:
        """Omit purchase consent while submitting a valid signed selection."""
        self.prepare_purchase(scenario)
        scenario.data.pop("confirm")

    def verify_purchase(self, response: HttpResponse) -> bool:
        """Verify the new line is persisted, assigned and provisioned exactly once."""
        line = self.connection.numbers.get(number="+32470000008")
        self.adapter.provision_number.assert_called_once()
        return (
            line.name == "Reception"
            and line.assigned_users.filter(pk=self.normal_user.pk).exists()
        )

    def verify_no_purchase(self, response: HttpResponse) -> bool:
        """Reject invalid requests before contacting the carrier purchase endpoint."""
        self.adapter.provision_number.assert_not_called()
        return not self.connection.numbers.filter(number="+32470000008").exists()

    def prepare_alternate_purchase(self, scenario: RequestScenario) -> None:
        """Submit carrier-specific options alongside shared consent and signed selection."""
        self.prepare_purchase(scenario)
        scenario.data["plan"] = "7"
        scenario.data["address_sid"] = "not-a-provider-field"

    def prepare_invalid_plan(self, scenario: RequestScenario) -> None:
        """Supply an invalid value for the alternate provider's required numeric option."""
        self.prepare_alternate_purchase(scenario)
        scenario.data["plan"] = "0"

    def prepare_search_failure(self, scenario: RequestScenario) -> None:
        """Simulate a provider-specific failure containing details that must not be rendered."""
        self.adapter.search_numbers.side_effect = RuntimeError("private-provider-error")

    def verify_alternate_search(self, response: HttpResponse) -> bool:
        """Verify schema-driven controls and dispatch without Twilio labels or filters."""
        self.adapter.search_numbers.assert_called_once_with({"territory": "North"})
        html = response.content.decode()
        return all(
            value in html
            for value in (
                "Service territory",
                "Service plan",
                "Example carrier purchase terms",
                "+32470000008",
            )
        ) and all(
            value not in html
            for value in ("Twilio", "address_sid", "bundle_sid", "Country code")
        )

    def verify_alternate_purchase(self, response: HttpResponse) -> bool:
        """Verify typed options and provider-specific callback routing reach the carrier."""
        self.adapter.provision_number.assert_called_once_with(
            "+32470000008",
            "Reception",
            {"plan": 7},
            {"events": "https://carrier.example.test/events"},
        )
        return self.verify_purchase(response)

    def prepare_no_provisioning(self, scenario: RequestScenario) -> None:
        """Declare a provider with inventory support but no provisioning controls."""
        provider = replace(
            VOIP_PROVIDER_REGISTRY.get(self.connection.provider),
            number_purchase_schema=None,
        )
        self.enterContext(
            patch.dict(VOIP_PROVIDER_REGISTRY._registry, {provider.key: provider})
        )
